import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = list(input_data[1])
    q = int(input_data[2])

    # mapping[char] stores what the character 'char' eventually becomes.
    # We track the transformation of each of the 26 lowercase letters.
    mapping = {chr(ord('a') + i): chr(ord('a') + i) for i in range(26)}

    idx = 3
    for _ in range(q):
        c = input_data[idx]
        d = input_data[idx+1]
        idx += 2

        if c == d:
            continue

        # All characters currently mapped to 'c' must now be mapped to 'd'
        for char in mapping:
            if mapping[char] == c:
                mapping[char] = d

    # Apply the final mapping to the original string
    result = []
    for char in s:
        result.append(mapping[char])

    print("".join(result))

if __name__ == "__main__":
    solve()

